  <input id="n2Input" type="range" min="1" max="2.5" step="0.01" value="1.5"
    oninput="document.getElementById('n2Val').value=(+this.value).toFixed(2);update_n2(+this.value)"></label>
<label><input id="showReflectedInput" type="checkbox" onchange="toggle_showReflected(this.checked)"> Show reflected ray</label>
<span style="font-size:11px;color:#666;line-height:1.4">Snell: n₁ sin θ₁ = n₂ sin θ₂. Hover any element for a hint; click for an explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var W = 620, H = 680;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var PX = 300, PY = 350;             // point of incidence
  var C_RAY = '#0026E6';              // thick saturated blue
  var C_REFL = '#3F86F5';             // lighter blue (partial reflection)
  var C_NORM = '#00A6F0';             // cyan normal
  var C_TIR = '#E2461B';

  // ---- state -------------------------------------------------------------
  var theta1 = 40, n1 = 1.0, n2 = 1.5, showReflected = false;

  // ---- z-order: rays (bottom) -> static geometry -> labels (top) ---------
  var gRays = draw.group();

  draw.line(0, PY, W, PY).stroke({ color: '#000', width: 7, linecap: 'butt' })
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Planar interface between medium 1 (above) and medium 2 (below)', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The interface', 'This flat boundary separates two transparent media with refractive indices n₁ and n₂. Light changes speed here, and that change of speed is what bends the ray.');
    });

  draw.line(PX, 40, PX, 632).stroke({ color: C_NORM, width: 2.5 })
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Surface normal: perpendicular to the interface', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
