<p id="demoNarration" style="margin:0;font-size:12px;line-height:1.45;color:#333">Drag the blue ray in the upper medium, or use the sliders. Press ▶ to start the 5-step guided tour.</p>
<div style="display:flex;align-items:center;gap:6px">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;color:#555">intro</span>
  <button onclick="nextStep()">▶</button>
</div>
<label>Angle of incidence θ₁ (deg): <output id="theta1Val">40</output>
  <input id="theta1Input" type="range" min="0" max="89" step="1" value="40"
    oninput="document.getElementById('theta1Val').value=this.value;update_theta1(+this.value)"></label>
<label>n₁ (upper medium): <output id="n1Val">1.00</output>
  <input id="n1Input" type="range" min="1" max="2.5" step="0.01" value="1"
    oninput="document.getElementById('n1Val').value=(+this.value).toFixed(2);update_n1(+this.value)"></label>
<label>n₂ (lower medium): <output id="n2Val">1.50</output>
  <input id="n2Input" type="range" min="1" max="2.5" step="0.01" value="1.5"
    oninput="document.getElementById('n2Val').value=(+this.value).toFixed(2);update_n2(+this.value)"></label>
<label><input id="showReflectedInput" type="checkbox" onchange="toggle_showReflected(this.checked)"> Show reflected ray</label>
<label><input id="showMeasureInput" type="checkbox" onchange="toggle_showMeasure(this.checked)"> Show angle arcs &amp; n·sin θ readout</label>
<span style="font-size:11px;color:#666;line-height:1.4">Snell: n₁ sin θ₁ = n₂ sin θ₂. Hover any element for a hint; click for an explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var W = 620, H = 680;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var PX = 300, PY = 350;             // point of incidence
  var C_RAY = '#0026E6';              // thick saturated blue
  var C_REFL = '#3F86F5';             // lighter blue (partial reflection)
  var C_NORM = '#00A6F0';             // cyan normal
  var C_TIR = '#E2461B';
  var SERIF = 'Georgia, "Times New Roman", serif';

  // ---- state -------------------------------------------------------------
  var theta1 = 40, n1 = 1.0, n2 = 1.5, showReflected = false, showMeasure = false;

  // ---- rich text with real subscripts (tspan, no unicode subscript glyphs) -
  function richText(parent, parts, size, family, color) {
    var shift = Math.round(size * 0.26);
    var t = parent.text(function (add) {
      var cur = 0;
      for (var i = 0; i < parts.length; i++) {
        var p = parts[i];
        var ts = add.tspan(p.t);
        var target = p.sub ? shift : 0;
        ts.dy(target - cur);
        cur = target;
        if (p.sub) ts.font({ size: Math.round(size * 0.64) });
        if (p.fill) ts.fill(p.fill);
      }
    }).font({ family: family || SERIF, size: size });
    if (color) t.fill(color);
    return t;
  }
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    return t;
  }
  function hookup(el, tip, title, body) {
    el.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup(title, body); });
  }

  // ---- z-order: rays (bottom) -> static geometry -> labels (top) ---------
  var gRays = draw.group();

  draw.line(0, PY, W, PY).stroke({ color: '#000', width: 7, linecap: 'butt' })
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Planar interface between medium 1 (above) and medium 2 (below)', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The interface', 'This flat boundary separates two transparent media with refractive indices n₁ and n₂. Light changes speed here, and that change of speed is what bends the ray.');
    });

  draw.line(PX, 40, PX, 612).stroke({ color: C_NORM, width: 2.5 })
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Surface normal: perpendicular to the interface', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Surface normal', 'All angles in Snell\'s law are measured from the normal, not from the surface. The normal is perpendicular to the interface, as marked by the small right-angle square.');
    });

  // right-angle square (upper-right quadrant)
  draw.polyline([[PX + 26, PY], [PX + 26, PY - 26], [PX, PY - 26]])
    .fill('none').stroke({ color: '#000', width: 2 });

  draw.text('surface\nnormal').font({ family: SERIF, size: 19, anchor: 'start', leading: 1.15 })
    .move(PX + 14, 42).fill('#000');

  var nlab1 = richText(draw, [{ t: 'n' }, { t: '1', sub: true }], 32, SERIF, '#000');
  nlab1.center(104, 308);
  hookup(nlab1, 'n₁ = index of the upper medium',
    'Index of the upper medium',
    'n₁ sets the speed of light above the boundary (v = c/n₁). A larger n means slower light and, for a given ray, a smaller angle to the normal inside that medium.');

  var nlab2 = richText(draw, [{ t: 'n' }, { t: '2', sub: true }], 32, SERIF, '#000');
  nlab2.center(104, 396);
  hookup(nlab2, 'n₂ = index of the lower medium',
    'Index of the lower medium',
    'n₂ sets the speed of light below the boundary. Because n·sin θ is conserved across the boundary, raising n₂ must lower sin θ₂ — the ray bends toward the normal.');

  var gLabels = draw.group();

  // ---- helpers -----------------------------------------------------------
  function clampLen(dx, dy, maxL) {
    var L = maxL;
    if (dx > 1e-6) L = Math.min(L, (W - 12 - PX) / dx);
    if (dx < -1e-6) L = Math.min(L, (PX - 12) / (-dx));
    if (dy > 1e-6) L = Math.min(L, (H - 30 - PY) / dy);
    if (dy < -1e-6) L = Math.min(L, (PY - 44) / (-dy));
    return L;
  }

  // ---- main render -------------------------------------------------------
  function render() {
    gRays.clear();
    gLabels.clear();

    var t1 = theta1 * Math.PI / 180;
    var s1 = Math.sin(t1);
    var prod1 = n1 * s1;
    var s2 = prod1 / n2;
    var tir = s2 > 1;
    var t2 = tir ? null : Math.asin(Math.min(1, s2));

    // ---------- incident ray ----------
    var idx = s1, idy = Math.cos(t1);            // travel direction (down-right)
    var Li = clampLen(-idx, -idy, 340);
    var ax = PX - Li * idx, ay = PY - Li * idy;
    var inc = gRays.line(ax, ay, PX, PY).stroke({ color: C_RAY, width: 6.5, linecap: 'round' });
    hookup(inc, 'Incident ray — θ₁ = ' + theta1.toFixed(0) + '°  (drag me)',
      'Incident ray',
      'This ray travels through medium 1 and strikes the boundary at θ₁ = ' + theta1.toFixed(0) +
      '° from the normal. Drag it with the mouse to swing the angle of incidence and watch how the transmitted ray responds.');

    // "ray direction" lettered along the ray
    var lx = PX - 0.70 * Li * idx, ly = PY - 0.70 * Li * idy;
    var perpx = idy, perpy = -idx;               // points up-right of the ray
    var rot = Math.atan2(idy, idx) * 180 / Math.PI;
    var rd = gLabels.text('ray direction')
      .font({ family: SERIF, size: 19, anchor: 'middle' }).fill('#000');
    rd.center(lx + 21 * perpx, ly + 21 * perpy);
    rd.rotate(rot, lx + 21 * perpx, ly + 21 * perpy);
    halo(rd);

    // ---------- refracted ray ----------
    if (!tir) {
      var rdx = Math.sin(t2), rdy = Math.cos(t2);
      var Lr = clampLen(rdx, rdy, 340);
      var refr = gRays.line(PX, PY, PX + Lr * rdx, PY + Lr * rdy)
        .stroke({ color: C_RAY, width: 6.5, linecap: 'round' });
      hookup(refr, 'Refracted ray — θ₂ = ' + (t2 * 180 / Math.PI).toFixed(1) + '°',
        'Refracted (transmitted) ray',
        'Snell\'s law fixes this direction: sin θ₂ = (n₁/n₂) sin θ₁ = ' + s2.toFixed(3) + ', so θ₂ = ' +
        (t2 * 180 / Math.PI).toFixed(1) + '°. The product n·sin θ is the same on both sides — that is the quantity that is conserved, not the angle.');
    }

    // ---------- reflected ray ----------
    if (showReflected || tir) {
      var fdx = idx, fdy = -idy;
      var Lf = clampLen(fdx, fdy, 320);
      var refl = gRays.line(PX, PY, PX + Lf * fdx, PY + Lf * fdy)
        .stroke({ color: tir ? C_RAY : C_REFL, width: tir ? 6.5 : 4, linecap: 'round' });
      if (!tir) refl.attr('stroke-dasharray', '10,7');
      hookup(refl, tir ? 'Totally reflected ray (100% of the light)' : 'Partially reflected ray (mirrored about the normal)',
        tir ? 'Total internal reflection' : 'Reflected ray',
        tir ? 'Snell\'s law would need sin θ₂ = ' + s2.toFixed(2) + ' > 1, which is impossible. No transmitted ray exists, so all the light is reflected back into medium 1 at the mirror angle θ₁.'
          : 'Some light always reflects at a boundary, leaving at the same angle θ₁ on the other side of the normal. Its share grows as θ₁ approaches grazing incidence.');
    }

    // ---------- angle labels (always) and arcs (measurement mode) ----------
    if (showMeasure && theta1 > 1.5) {
      var p1 = [];
      for (var i = 0; i <= 28; i++) {
        var f = t1 * i / 28;
        p1.push([PX - 86 * Math.sin(f), PY - 86 * Math.cos(f)]);
      }
      gLabels.polyline(p1).fill('none').stroke({ color: '#555', width: 1.2 });
    }
    var a1 = t1 / 2 + (theta1 < 12 ? 0.20 : 0);
    var th1 = richText(gLabels, [{ t: '\u03B8' }, { t: '1', sub: true }], 28, SERIF, '#000');
    th1.center(PX - 122 * Math.sin(a1), PY - 122 * Math.cos(a1));
    halo(th1);
    hookup(th1, 'θ₁ = ' + theta1.toFixed(0) + '° — measured from the normal',
      'Angle of incidence',
      'θ₁ is the angle between the incoming ray and the normal (not the surface). Snell\'s law uses sin θ₁, so equal steps in θ₁ do not give equal steps in θ₂.');

    if (!tir) {
      var d2 = t2 * 180 / Math.PI;
      if (showMeasure && d2 > 1.5) {
        var p2 = [];
        for (var j = 0; j <= 28; j++) {
          var g = t2 * j / 28;
          p2.push([PX + 72 * Math.sin(g), PY + 72 * Math.cos(g)]);
        }
        gLabels.polyline(p2).fill('none').stroke({ color: '#555', width: 1.2 });
      }
      var a2 = t2 / 2 + (d2 < 12 ? 0.20 : 0);
      var th2 = richText(gLabels, [{ t: '\u03B8' }, { t: '2', sub: true }], 28, SERIF, '#000');
      th2.center(PX + 166 * Math.sin(a2), PY + 166 * Math.cos(a2));
      halo(th2);
      hookup(th2, 'θ₂ = ' + d2.toFixed(1) + '° — refraction angle',
        'Angle of refraction',
        'θ₂ satisfies n₂ sin θ₂ = n₁ sin θ₁. When n₂ > n₁ it is smaller than θ₁ (bent toward the normal); when n₂ < n₁ it is larger (bent away).');
    }

    // ---------- measurement extras ----------
    if (showMeasure) {
      gLabels.circle(11).center(PX, PY).fill(C_RAY).stroke({ color: '#fff', width: 1.5 });

      var box = gLabels.group();
      box.rect(222, 96).move(14, 540).fill('#ffffff').opacity(0.9)
        .stroke({ color: '#dcdcdc', width: 1 }).radius(4);
      var S = 15, F = 'ui-monospace, Consolas, monospace';
      var deg2 = tir ? '\u2014' : (t2 * 180 / Math.PI).toFixed(1) + '\u00B0';
      richText(box, [{ t: 'n' }, { t: '1', sub: true }, { t: ' = ' + n1.toFixed(2) + '   n' },
        { t: '2', sub: true }, { t: ' = ' + n2.toFixed(2) }], S, F, '#222').move(24, 548);
      richText(box, [{ t: '\u03B8' }, { t: '1', sub: true }, { t: ' = ' + theta1.toFixed(0) + '\u00B0   \u03B8' },
        { t: '2', sub: true }, { t: ' = ' + deg2 }], S, F, '#222').move(24, 570);
      richText(box, [{ t: 'n' }, { t: '1', sub: true }, { t: ' sin \u03B8' }, { t: '1', sub: true },
        { t: ' = ' + prod1.toFixed(3) }], S, F, C_RAY).move(24, 592);
      richText(box, [{ t: 'n' }, { t: '2', sub: true }, { t: ' sin \u03B8' }, { t: '2', sub: true },
        { t: ' = ' + (tir ? 'impossible' : (n2 * Math.sin(t2)).toFixed(3)) }],
        S, F, tir ? C_TIR : C_RAY).move(24, 614);
      hookup(box, 'The invariant: n₁ sin θ₁ must equal n₂ sin θ₂',
        'The conserved quantity',
        'Watch these two products while you drag: they stay equal. That is Snell\'s law. Total internal reflection happens exactly when n₁ sin θ₁ exceeds n₂, because then no angle θ₂ can match it.');
    }

    // ---------- TIR caption ----------
    if (tir) {
      var thc = Math.asin(Math.min(1, n2 / n1)) * 180 / Math.PI;
      halo(gLabels.text('Total internal reflection').font({ family: SERIF, size: 19 })
        .fill(C_TIR).move(18, 432));
      halo(richText(gLabels, [{ t: '\u03B8' }, { t: 'c', sub: true }, { t: ' = arcsin(n' },
        { t: '2', sub: true }, { t: '/n' }, { t: '1', sub: true }, { t: ') = ' + thc.toFixed(1) + '\u00B0' }],
        17, SERIF, C_TIR).move(18, 460));
    }
  }

  // ---- control handlers (global) -----------------------------------------
  window.update_theta1 = function (v) { theta1 = v; render(); };
  window.update_n1 = function (v) { n1 = v; render(); };
  window.update_n2 = function (v) { n2 = v; render(); };
  window.toggle_showReflected = function (on) { showReflected = on; render(); };
  window.toggle_showMeasure = function (on) { showMeasure = on; render(); };

  function setControls(st) {
    if ('theta1' in st) {
      theta1 = st.theta1;
      document.getElementById('theta1Input').value = st.theta1;
      document.getElementById('theta1Val').value = st.theta1;
    }
    if ('n1' in st) {
      n1 = st.n1;
      document.getElementById('n1Input').value = st.n1;
      document.getElementById('n1Val').value = st.n1.toFixed(2);
    }
    if ('n2' in st) {
      n2 = st.n2;
      document.getElementById('n2Input').value = st.n2;
      document.getElementById('n2Val').value = st.n2.toFixed(2);
    }
    if ('showReflected' in st) {
      showReflected = st.showReflected;
      document.getElementById('showReflectedInput').checked = st.showReflected;
    }
    if ('showMeasure' in st) {
      showMeasure = st.showMeasure;
      document.getElementById('showMeasureInput').checked = st.showMeasure;
    }
    render();
  }

  // ---- drag the incident ray ---------------------------------------------
  var dragging = false;
  function toLocal(e) {
    var pt = draw.node.createSVGPoint();
    pt.x = e.clientX; pt.y = e.clientY;
    return pt.matrixTransform(draw.node.getScreenCTM().inverse());
  }
  function setFromPoint(p) {
    var dx = p.x - PX, dy = p.y - PY;
    if (dy > -6) dy = -6;
    var ang = Math.atan2(-dx, -dy) * 180 / Math.PI;
    ang = Math.max(0, Math.min(89, ang));
    setControls({ theta1: Math.round(ang) });
  }
  draw.node.addEventListener('mousedown', function (e) {
    var p = toLocal(e);
    if (p.y < PY - 8) { dragging = true; setFromPoint(p); e.preventDefault(); }
  });
  window.addEventListener('mousemove', function (e) { if (dragging) setFromPoint(toLocal(e)); });
  window.addEventListener('mouseup', function () { dragging = false; });

  // ---- demo steps ---------------------------------------------------------
  var steps = [
    { title: 'Normal incidence: no bending',
      narration: 'With the ray straight down the normal, θ₁ = 0 and θ₂ = 0 — a ray hitting the surface head-on passes through undeviated no matter what the indices are.',
      state: { theta1: 0, n1: 1, n2: 1.5, showReflected: false, showMeasure: true } },
    { title: 'Entering a denser medium bends toward the normal',
      narration: 'Tilt the ray to 40°. Because n₂ > n₁, the refracted ray makes a smaller angle with the normal: sin θ₂ = (n₁/n₂) sin θ₁, so θ₂ ≈ 25°. Compare the two products in the readout — they match.',
      state: { theta1: 40, n1: 1, n2: 1.5, showReflected: false, showMeasure: true } },
    { title: 'Raising n₂ bends the ray even harder',
      narration: 'Push n₂ up toward 2.4 (diamond). The refracted ray swings closer to the normal — the stronger the index contrast, the sharper the bend, because n₂ sin θ₂ must still equal n₁ sin θ₁.',
      state: { theta1: 60, n1: 1, n2: 2.4, showReflected: false, showMeasure: true } },
    { title: 'Reversing the contrast bends away from the normal',
      narration: 'Now make the upper medium the dense one (n₁ = 1.5, n₂ = 1.0). The refracted ray swings away from the normal, flattening toward the surface, and a partial reflection appears.',
      state: { theta1: 30, n1: 1.5, n2: 1, showReflected: true, showMeasure: true } },
    { title: 'Past the critical angle: total internal reflection',
      narration: 'Keep n₁ > n₂ and push θ₁ past θ_c = arcsin(n₂/n₁) ≈ 42°. Snell\'s law would demand sin θ₂ > 1, which is impossible — the refracted ray vanishes and all the light reflects back, mirrored about the normal.',
      state: { theta1: 55, n1: 1.5, n2: 1, showReflected: true, showMeasure: true } }
  ];
  var stepIdx = -1;
  function paintStep() {
    var t = document.getElementById('stepTitle');
    var n = document.getElementById('demoNarration');
    var l = document.getElementById('stepLabel');
    if (stepIdx < 0) {
      t.textContent = 'Explore mode';
      n.textContent = 'Drag the blue ray in the upper medium, or use the sliders. Press ▶ to start the 5-step guided tour.';
      l.textContent = 'intro';
    } else {
      t.textContent = steps[stepIdx].title;
      n.textContent = steps[stepIdx].narration;
      l.textContent = (stepIdx + 1) + ' / ' + steps.length;
    }
  }
  window.nextStep = function () {
    if (stepIdx < steps.length - 1) { stepIdx++; setControls(steps[stepIdx].state); paintStep(); }
  };
  window.prevStep = function () {
    if (stepIdx > 0) { stepIdx--; setControls(steps[stepIdx].state); paintStep(); }
    else if (stepIdx === 0) {
      stepIdx = -1;
      setControls({ theta1: 40, n1: 1, n2: 1.5, showReflected: false, showMeasure: false });
      paintStep();
    }
  };

  // ---- initial (faithful) state ------------------------------------------
  setControls({ theta1: 40, n1: 1, n2: 1.5, showReflected: false, showMeasure: false });
  paintStep();
  window.__markRendered();
})();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.
